-- United Arab Emirates milestone translations (ES/DE/FR)
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-dict-consult', 'es', 'Se publica el Diccionario de Datos PINT AE para consulta pública', 'La especificación Peppol PINT localizada de los EAU se abre para recabar opiniones de las partes interesadas, con versiones actualizadas a medida que se integran las aportaciones.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-ministerial-decisions', 'es', 'Se emiten las Decisiones Ministeriales n.º 243 y 244 de 2025', 'El Ministerio de Finanzas adopta formalmente PINT AE como el Diccionario de Datos de los EAU y establece el Sistema de Facturación Electrónica y su implementación, bajo la autoridad del Decreto-Ley Federal n.º 8 de 2017 sobre el IVA.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-first-asps', 'es', 'Se publican los primeros Proveedores de Servicios Acreditados (ASP)', 'El MoF publica su primera lista de proveedores de servicios acreditados, que se amplía progresivamente a medida que más proveedores completan la acreditación.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-penalty-framework', 'es', 'La Decisión del Gabinete n.º 106 de 2025 establece el régimen sancionador', 'Se definen seis categorías específicas de infracciones de facturación electrónica con sanciones fijas, junto con la Decisión del Gabinete n.º 129 de 2025, que revisa por separado las sanciones en todo el marco fiscal de los EAU, creando una posible "doble exposición sancionadora."', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-pilot', 'es', 'Comienza la fase piloto voluntaria de facturación electrónica', 'Se abre la participación voluntaria antes del mandato, permitiendo a las empresas probar la conectividad con un Proveedor de Servicios Acreditado (ASP) y el formato de factura PINT AE sin riesgo antes de que se apliquen sanciones.', '["Considere unirse al piloto voluntario para resolver problemas de integración con el ASP antes de la fase obligatoria", "Vigile las actualizaciones de orientación técnica de la Autoridad Federal de Impuestos (FTA)"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-asp', 'es', 'Plazo de nombramiento de ASP — empresas con ingresos ≥ AED 50 millones', 'Las empresas con ingresos de AED 50 millones o más deben haber nombrado a un Proveedor de Servicios Acreditado (ASP) antes de la entrada en vigor de enero de 2027 (plazo ampliado desde el 31 de julio de 2026).', '["Seleccione y contrate a un Proveedor de Servicios Acreditado por la FTA", "Comience las pruebas de integración PINT AE (UBL 2.1) con su ASP"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-phase1', 'es', 'Entrada en vigor obligatoria de la Fase 1 — ingresos ≥ AED 50 millones', 'La facturación electrónica estructurada pasa a ser obligatoria para las grandes empresas, transmitida a través de un ASP por la red Peppol en formato PINT AE, con una copia en tiempo real reportada a la FTA.', '["Complete la integración con el ASP y las pruebas de extremo a extremo antes de la entrada en vigor", "Asegúrese de que las facturas incluyan todos los campos de datos exigidos por la FTA — el PDF y el papel ya no son válidos"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-phase2', 'es', 'El mandato se extiende a todas las demás empresas registradas a efectos del IVA', 'El mandato de facturación electrónica se amplía para cubrir a todas las empresas restantes registradas a efectos del IVA en transacciones B2B/B2G, con obligaciones específicas G2B/B2G a partir de octubre de 2027.', '["Confirme su estado de registro de IVA y nombre a un ASP con suficiente antelación a esta fecha", "Las transacciones intragrupo dentro de un mismo grupo de IVA de los EAU tienen una transición ampliada hasta el 1 de enero de 2029"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-dict-consult', 'de', 'PINT-AE-Datenwörterbuch zur öffentlichen Konsultation veröffentlicht', 'Die lokalisierte Peppol-PINT-Spezifikation der VAE wird für Stakeholder-Feedback geöffnet, mit aktualisierten Versionen, sobald die Rückmeldungen eingearbeitet sind.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-ministerial-decisions', 'de', 'Ministerialbeschlüsse Nr. 243 und 244 von 2025 erlassen', 'Das Finanzministerium übernimmt PINT AE formell als VAE-Datenwörterbuch und legt das elektronische Rechnungssystem und dessen Umsetzung fest, gestützt auf das Bundesdekretgesetz Nr. 8 von 2017 zur Mehrwertsteuer.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-first-asps', 'de', 'Erste akkreditierte Dienstanbieter (ASPs) veröffentlicht', 'Das MoF veröffentlicht seine erste Liste akkreditierter Dienstanbieter, die schrittweise erweitert wird, sobald weitere Anbieter die Akkreditierung abschließen.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-penalty-framework', 'de', 'Kabinettsbeschluss Nr. 106 von 2025 legt den Sanktionsrahmen fest', 'Sechs spezifische Kategorien von E-Invoicing-Verstößen werden mit festen Bußgeldern definiert, zusammen mit Kabinettsbeschluss Nr. 129 von 2025, der separat die Bußgelder im gesamten VAE-Steuerrahmen überarbeitet — was eine mögliche "doppelte Bußgeldexposition" schafft.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-pilot', 'de', 'Freiwillige E-Invoicing-Pilotphase beginnt', 'Die freiwillige Teilnahme wird vor dem Mandat geöffnet, sodass Unternehmen die Konnektivität mit einem akkreditierten Dienstanbieter (ASP) und das PINT-AE-Rechnungsformat risikofrei testen können, bevor Bußgelder gelten.', '["Erwägen Sie die Teilnahme am freiwilligen Pilotprogramm, um ASP-Integrationsprobleme vor der verpflichtenden Phase zu lösen", "Verfolgen Sie Aktualisierungen der technischen Hinweise der Federal Tax Authority (FTA)"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-asp', 'de', 'Frist zur ASP-Bestellung — Unternehmen mit Umsatz ≥ AED 50 Millionen', 'Unternehmen mit einem Umsatz von AED 50 Millionen oder mehr müssen bis zu diesem Datum einen akkreditierten Dienstanbieter (ASP) bestellt haben, vor dem Start im Januar 2027 (Frist verlängert vom 31. Juli 2026).', '["Wählen Sie einen von der FTA akkreditierten Dienstanbieter aus und schließen Sie einen Vertrag ab", "Beginnen Sie die PINT-AE-Integrationstests (UBL 2.1) mit Ihrem ASP"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-phase1', 'de', 'Verpflichtender Start Phase 1 — Umsatz ≥ AED 50 Millionen', 'Strukturiertes E-Invoicing wird für Großunternehmen verpflichtend, übermittelt über einen ASP im Peppol-Netzwerk im PINT-AE-Format, mit einer in Echtzeit an die FTA gemeldeten Kopie.', '["Schließen Sie die ASP-Integration und Ende-zu-Ende-Tests vor dem Start ab", "Stellen Sie sicher, dass Rechnungen alle von der FTA geforderten Datenfelder enthalten — PDF und Papier gelten nicht mehr"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-phase2', 'de', 'Das Mandat wird auf alle übrigen umsatzsteuerlich registrierten Unternehmen ausgeweitet', 'Das E-Invoicing-Mandat wird auf alle verbleibenden umsatzsteuerlich registrierten Unternehmen für B2B-/B2G-Transaktionen ausgeweitet, mit spezifischen G2B-/B2G-Pflichten ab Oktober 2027.', '["Bestätigen Sie Ihren Umsatzsteuer-Registrierungsstatus und bestellen Sie rechtzeitig vor diesem Datum einen ASP", "Konzerninterne Transaktionen innerhalb einer einzigen VAE-Umsatzsteuergruppe haben eine verlängerte Übergangsfrist bis zum 1. Januar 2029"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-dict-consult', 'fr', 'Le dictionnaire de données PINT AE est publié pour consultation publique', 'La spécification Peppol PINT localisée des Émirats arabes unis est ouverte aux retours des parties prenantes, avec des versions mises à jour au fur et à mesure de l''intégration des contributions.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-ministerial-decisions', 'fr', 'Les décisions ministérielles n° 243 et 244 de 2025 sont émises', 'Le ministère des Finances adopte formellement PINT AE comme dictionnaire de données des EAU et établit le système de facturation électronique ainsi que sa mise en œuvre, en vertu du décret-loi fédéral n° 8 de 2017 relatif à la TVA.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-first-asps', 'fr', 'Publication des premiers prestataires de services accrédités (ASP)', 'Le MoF publie sa première liste de prestataires de services accrédités, qui s''élargit progressivement à mesure que d''autres prestataires obtiennent l''accréditation.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-penalty-framework', 'fr', 'La décision du Cabinet n° 106 de 2025 fixe le régime des sanctions', 'Six catégories spécifiques d''infractions à la facturation électronique sont définies avec des sanctions fixes, aux côtés de la décision du Cabinet n° 129 de 2025, qui révise séparément les sanctions dans l''ensemble du cadre fiscal des EAU — créant une possible « double exposition aux sanctions ».', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-pilot', 'fr', 'La phase pilote volontaire de facturation électronique débute', 'La participation volontaire est ouverte avant le mandat, permettant aux entreprises de tester la connectivité avec un prestataire de services accrédité (ASP) et le format de facture PINT AE sans risque avant l''application des sanctions.', '["Envisagez de rejoindre le programme pilote volontaire pour résoudre les problèmes d''intégration ASP avant la phase obligatoire", "Surveillez les mises à jour des orientations techniques de l''Autorité fédérale des impôts (FTA)"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-asp', 'fr', 'Échéance de désignation de l''ASP — entreprises dont le chiffre d''affaires est ≥ 50 millions AED', 'Les entreprises dont le chiffre d''affaires est égal ou supérieur à 50 millions d''AED doivent avoir désigné un prestataire de services accrédité (ASP) avant l''entrée en vigueur de janvier 2027 (échéance prolongée depuis le 31 juillet 2026).', '["Sélectionnez et contractez avec un prestataire de services accrédité par la FTA", "Commencez les tests d''intégration PINT AE (UBL 2.1) avec votre ASP"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-phase1', 'fr', 'Entrée en vigueur obligatoire de la phase 1 — chiffre d''affaires ≥ 50 millions AED', 'La facturation électronique structurée devient obligatoire pour les grandes entreprises, transmise via un ASP sur le réseau Peppol au format PINT AE, avec une copie transmise en temps réel à la FTA.', '["Achevez l''intégration avec l''ASP et les tests de bout en bout avant l''entrée en vigueur", "Assurez-vous que les factures comportent tous les champs de données exigés par la FTA — le PDF et le papier ne sont plus valables"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uae-phase2', 'fr', 'Le mandat s''étend à toutes les autres entreprises immatriculées à la TVA', 'Le mandat de facturation électronique s''élargit pour couvrir toutes les entreprises restantes immatriculées à la TVA pour les transactions B2B/B2G, avec des obligations spécifiques G2B/B2G à partir d''octobre 2027.', '["Confirmez votre statut d''immatriculation à la TVA et désignez un ASP bien avant cette date", "Les transactions intragroupe au sein d''un même groupe TVA des EAU bénéficient d''une transition prolongée jusqu''au 1er janvier 2029"]');
